/**
 * Synthetic data for a home, generated by the benchmark and holding nothing personal.
 *
 * - Chats: upstream's synthetic Session corpus (`benchmarks/session-corpus/synthetic-corpus.ts`), whose per-Session
 *   length follows aggregate quantiles of a measured corpus and whose text comes from a fixed synthetic vocabulary.
 *   It is deterministic: the same count writes the same bytes. A corpus is written once per count into the benchmark
 *   cache and copied into each home's `sessions/`.
 * - Plugins: installed plugin packages in the profile's `node_modules` and its `package.json` dependencies, each a
 *   manifest with a version and no code, so the update report reads one plugin fact per package as it does for an
 *   installed plugin. They load no row, so the Host does not boot them.
 *
 * @module @delo/benchmarks/fixtures/data
 */
import { execFileSync } from 'node:child_process'
import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { removeTree } from '../harness/roots.ts'
import { PROFILE } from './home.ts'

/** The parts of upstream's corpus modules the benchmark uses. */
export interface CorpusModules {
  /** `corpus-shape.ts`: the anchor and turns of a chat's length. */
  readonly sessionShape: (rank: number, count: number) => { readonly anchor: number, readonly turns: number }
  /** `synthetic-corpus.ts`: a chat's id. */
  readonly corpusSessionId: (rank: number) => string
  /** `synthetic-corpus.ts`: a chat's stored header. */
  readonly corpusHeader: (rank: number, count: number) => { readonly cwd?: string, readonly createdAt: number }
  /** `synthetic-corpus.ts`: whether a chat is a subagent's. */
  readonly subagentRank: (rank: number) => boolean
  /** `synthetic-corpus.ts`: the writer. */
  readonly SyntheticCorpusWriter: new () => {
    author(anchor: number): Promise<unknown>
    writeCorpus(root: string, count: number): Promise<{ readonly facts: { readonly compressedBytes: number } }>
  }
}

/** Upstream's corpus modules, as `@deepseek-ai/dsh-benchmarks` names them. */
const CORPUS_MODULES: { readonly shape: string, readonly corpus: string } = {
  shape: '@deepseek-ai/dsh-benchmarks/session-corpus/corpus-shape.ts',
  corpus: '@deepseek-ai/dsh-benchmarks/session-corpus/synthetic-corpus.ts',
}

/**
 * Load upstream's corpus modules. The specifiers are not literals, so this package's program does not typecheck
 * upstream's benchmark sources, which upstream's own benchmark build checks under its configuration.
 * @returns the functions and the writer.
 */
export async function corpusModules(): Promise<CorpusModules> {
  // A non-literal specifier gives the module untyped; the interface above states the part used.
  const shape: Pick<CorpusModules, 'sessionShape'> = await import(CORPUS_MODULES.shape)
  const corpus: Omit<CorpusModules, 'sessionShape'> = await import(CORPUS_MODULES.corpus)
  return { sessionShape: shape.sessionShape, corpusSessionId: corpus.corpusSessionId, corpusHeader: corpus.corpusHeader, subagentRank: corpus.subagentRank, SyntheticCorpusWriter: corpus.SyntheticCorpusWriter }
}

/**
 * The ids of the first chats of a synthetic corpus.
 * @param count - how many.
 * @returns their ids, in rank order.
 */
export async function chatIds(count: number): Promise<readonly string[]> {
  const { corpusSessionId } = await corpusModules()
  return Array.from({ length: count }, (_, rank) => corpusSessionId(rank))
}

/** What a written chat corpus holds. */
export interface ChatCorpus {
  /** The `sessions/` directory to copy. */
  readonly sessions: string
  /** Chats. */
  readonly chats: number
  /** Stored bytes. */
  readonly bytes: number
}

/**
 * The chat corpus of a size, written into the cache when it is not there yet.
 * @param cache - the benchmark cache.
 * @param chats - how many chats.
 * @param log - receives progress text.
 * @returns the corpus.
 */
export async function chatCorpus(cache: string, chats: number, log: (text: string) => void): Promise<ChatCorpus> {
  const directory = join(cache, 'chats', String(chats))
  const facts = join(directory, 'facts.json')
  if (existsSync(facts)) return { sessions: join(directory, 'sessions'), ...JSON.parse(readFileSync(facts, 'utf8')) as { chats: number, bytes: number } }
  log(`writing a synthetic corpus of ${String(chats)} chats`)
  const work = `${directory}.writing`
  removeTree(work)
  mkdirSync(work, { recursive: true })
  const { SyntheticCorpusWriter, sessionShape } = await corpusModules()
  const writer = new SyntheticCorpusWriter()
  const anchors = [...new Set(Array.from({ length: chats }, (_, rank) => sessionShape(rank, chats).anchor))].sort((a, b) => a - b)
  for (const anchor of anchors) await writer.author(anchor)
  const written = await writer.writeCorpus(join(work, 'sessions'), chats)
  writeFileSync(join(work, 'facts.json'), `${JSON.stringify({ chats, bytes: written.facts.compressedBytes })}\n`)
  removeTree(directory)
  mkdirSync(join(cache, 'chats'), { recursive: true })
  renameSync(work, directory)
  return { sessions: join(directory, 'sessions'), chats, bytes: written.facts.compressedBytes }
}

/**
 * Copy a corpus into a Delo home's `sessions/`, beside what is there.
 * @param corpus - the corpus.
 * @param deloHome - the Delo home.
 */
export function addChats(corpus: ChatCorpus, deloHome: string): void {
  mkdirSync(join(deloHome, 'sessions'), { recursive: true })
  execFileSync('cp', ['-a', `${corpus.sessions}/.`, join(deloHome, 'sessions')])
}

/**
 * The name of the synthetic plugin at an index.
 * @param index - the index.
 * @returns `@delo-benchmark/plugin-<nn>`.
 */
export function syntheticPluginName(index: number): string {
  return `@delo-benchmark/plugin-${String(index).padStart(2, '0')}`
}

/**
 * Add installed plugin packages to the CLI profile: each package's manifest under `node_modules` and a dependency in
 * the profile's `package.json`. Each declares the DSH and Delo ranges given, as a maintained plugin does, so the report
 * judges each one instead of naming it unpredictable.
 * @param deloHome - the Delo home.
 * @param count - how many.
 * @param engines - the `engines` each declares, such as `{ dsh: '>=0.2.2-rc.1', delo: '>=0.1.0' }`.
 */
export function addPlugins(deloHome: string, count: number, engines: Readonly<Record<string, string>>): void {
  const profile = join(deloHome, 'profiles', PROFILE)
  const manifestPath = join(profile, 'package.json')
  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8')) as { dependencies?: Record<string, string> }
  const dependencies = { ...manifest.dependencies }
  for (let index = 0; index < count; index++) {
    const name = syntheticPluginName(index)
    const directory = join(profile, 'node_modules', ...name.split('/'))
    mkdirSync(directory, { recursive: true })
    writeFileSync(join(directory, 'package.json'), `${JSON.stringify({ name, version: '1.0.0', type: 'module', description: 'A synthetic plugin package of the benchmark; it holds no code.', engines }, undefined, 2)}\n`)
    dependencies[name] = '1.0.0'
  }
  writeFileSync(manifestPath, `${JSON.stringify({ ...manifest, dependencies }, undefined, 2)}\n`)
}

/**
 * The upstream release the measured tree is based on, from the divergence ledger's `upstream.ref` (`dsh-v<version>`).
 * @param repository - the repository root.
 * @returns the version, such as `0.2.2-rc.1`.
 * @throws {Error} when the ledger names no `dsh-v` tag.
 */
export function upstreamVersion(repository: string): string {
  const ledger = JSON.parse(readFileSync(join(repository, 'delo', 'upstream-patches.json'), 'utf8')) as { readonly upstream?: { readonly ref?: string } }
  const match = /^dsh-v(.+)$/u.exec(ledger.upstream?.ref ?? '')
  if (match === null) throw new Error('delo/upstream-patches.json names no dsh-v<version> upstream ref')
  return match[1]!
}
